// Types and loaders for the course content in public/data (generated by tools/build_app_data.py)
export type Drill = { n: number; prompt: string; formula: number | null; hl: string[]; audio?: string; answers: string[] };
export type LessonPage = { n: number; items: Drill[]; quizzes: { quiz: string }[] };
export type Lesson = { id: string; num: string; title: string; stage: string; subs: string[]; pages: LessonPage[] };
export type Stage = { id: string; title: string; desc: string };
export type Course = { stages: Stage[]; lessons: Lesson[]; placement: string[] };
export type Option = { text: string; feedback: string; correct: boolean };
export type Quiz =
  | { id: string; title: string; type: "multiple-choice"; questions: { question: string; options: Option[] }[] }
  | { id: string; title: string; type: "sentence-order"; segments: string[]; answers: string[] }
  | { id: string; title: string; type: "matching"; pairs: { left: string; right: string }[] };
export type Voice = { right: string[]; wrong: string[] };
export type Homenaje = { secciones: { id: string; titulo: string; texto: string; imagen?: string }[] };

const get = <T,>(p: string): Promise<T> => fetch(p).then((r) => r.json());
export type AllData = { course: Course; quizzes: Record<string, Quiz>; voice: Voice; homenaje: Homenaje };
export async function loadAll(): Promise<AllData> {
  const [course, qs, voice, homenaje] = await Promise.all([
    get<Course>("/data/course.json"), get<Quiz[]>("/data/quizzes.json"),
    get<Voice>("/data/voice.json"), get<Homenaje>("/data/homenaje.json"),
  ]);
  return { course, quizzes: Object.fromEntries(qs.map((q) => [q.id, q])), voice, homenaje };
}
export const FORMULAS: Record<number, [string, string]> = {
  1: ["Afirmativa", "S + V + C"], 2: ["Afirmativa con 21", "S + 21 + V + C"], 3: ["Negativa", "S + 21 + N + V + C"],
  4: ["Interrogativa", "21 + S + V + C"], 5: ["Interrogativa negativa", "21 + N + S + V + C"],
};
